package thaumcraft.verification;

import java.util.*;
import java.util.function.BiConsumer;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.Vec3;
import net.neoforged.neoforge.capabilities.Capabilities;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
import net.neoforged.neoforge.fluids.*;
import net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction;
import thaumcraft.registry.R4Content;
import thaumcraft.production.ArcaneSpaBlockEntity;
import thaumcraft.menu.ArcaneSpaMenu;

final class SpaVerification {
    private static final BlockPos POS=new BlockPos(1648,120,0);
    private static ArcaneSpaBlockEntity create(ServerLevel l,BlockPos p){l.getChunkAt(p);l.setBlockAndUpdate(p,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p,R4Content.ARCANE_SPA.get().defaultBlockState());return (ArcaneSpaBlockEntity)l.getBlockEntity(p);}
    private static void interval(ArcaneSpaBlockEntity spa){for(int i=0;i<40;i++)spa.serverTick();}
    static void run(ServerLevel l,BiConsumer<Boolean,String> check){
        for(int x=-4;x<=30;x++)for(int z=-4;z<=4;z++){var p=POS.offset(x,0,z);l.getChunkAt(p);l.setBlockAndUpdate(p,Blocks.STONE.defaultBlockState());for(int y=1;y<=3;y++)l.setBlockAndUpdate(p.above(y),Blocks.AIR.defaultBlockState());}
        var spa=create(l,POS);var cap=l.getCapability(Capabilities.FluidHandler.BLOCK,POS,Direction.NORTH);check.accept(cap!=null&&cap.getTankCapacity(0)==5000&&l.getCapability(Capabilities.FluidHandler.BLOCK,POS,Direction.UP)==null,"native spa tank holds five buckets and rejects top-side automation");
        check.accept(cap.fill(new FluidStack(Fluids.WATER,6000),FluidAction.SIMULATE)==5000&&spa.tank.isEmpty(),"simulated native fill respects capacity without changing tank");check.accept(cap.fill(new FluidStack(Fluids.WATER,6000),FluidAction.EXECUTE)==5000&&spa.tank.getFluidAmount()==5000,"executed native fill clamps water to five buckets");check.accept(cap.fill(new FluidStack(Fluids.LAVA,1000),FluidAction.EXECUTE)==0,"filled tank refuses a different incoming fluid");
        spa.serverTick();check.accept(l.getBlockState(POS.above()).isAir()&&spa.tank.getFluidAmount()==5000,"mixing waits for bath salts without spending water");spa.setItem(0,new ItemStack(R4Content.BATH_SALTS.get(),32));interval(spa);check.accept(l.getBlockState(POS.above()).is(R4Content.PURIFYING_FLUID.get())&&l.getFluidState(POS.above()).isSource()&&spa.tank.getFluidAmount()==4000&&spa.getItem(0).getCount()==31,"spa places one full purifying source using one salt and one bucket");
        for(int i=0;i<39;i++)spa.serverTick();check.accept(spa.tank.getFluidAmount()==4000,"placement does not repeat during the first thirty-nine ticks");spa.serverTick();check.accept(l.getFluidState(POS.above().west()).isSource()&&spa.tank.getFluidAmount()==3000,"fortieth tick expands to first cardinally adjacent supported source");
        for(int i=0;i<23;i++){spa.tank.fill(new FluidStack(Fluids.WATER,5000),FluidAction.EXECUTE);interval(spa);}int sources=0;for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)if(l.getFluidState(POS.offset(x,1,z)).isSource())sources++;check.accept(sources==25&&spa.getItem(0).getCount()==7,"source expansion fills the entire original five-by-five footprint with one salt per source");var remaining=spa.tank.getFluidAmount();interval(spa);check.accept(spa.tank.getFluidAmount()==remaining&&spa.getItem(0).getCount()==7&&!l.getFluidState(POS.offset(-3,1,0)).isSource(),"full pool neither consumes ingredients nor expands beyond five-by-five bounds");
        var p=POS.east(8);var other=create(l,p);other.tank.fill(new FluidStack(Fluids.WATER,5000),FluidAction.EXECUTE);other.setItem(0,new ItemStack(R4Content.BATH_SALTS.get(),5));l.setBlockAndUpdate(p.above(),Blocks.STONE.defaultBlockState());other.serverTick();check.accept(other.tank.getFluidAmount()==5000,"solid block above spa prevents placement and ingredient loss");l.setBlockAndUpdate(p.above(),Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());interval(other);check.accept(l.getBlockState(p.above()).isAir()&&other.tank.getFluidAmount()==5000,"redstone disables placement without consuming salts or fluid");l.setBlockAndUpdate(p.east(),Blocks.AIR.defaultBlockState());interval(other);check.accept(other.tank.getFluidAmount()==4000,"spa resumes placing when redstone is removed");
        var itemCap=l.getCapability(Capabilities.ItemHandler.BLOCK,p,Direction.WEST);check.accept(itemCap!=null&&itemCap.insertItem(0,new ItemStack(Items.COAL),false).getCount()==1&&l.getCapability(Capabilities.ItemHandler.BLOCK,p,Direction.UP)==null,"native item automation accepts bath salts only and is unavailable above spa");check.accept(itemCap.insertItem(0,new ItemStack(R4Content.BATH_SALTS.get()),false).isEmpty(),"native side hopper inserts bath salts");
        var rawPos=POS.east(16);var raw=create(l,rawPos);raw.tank.fill(new FluidStack(Fluids.LAVA,1000),FluidAction.EXECUTE);raw.setItem(0,new ItemStack(R4Content.BATH_SALTS.get(),3));raw.serverTick();check.accept(raw.tank.getFluidAmount()==1000&&l.getBlockState(rawPos.above()).isAir(),"mix mode rejects lava rather than producing purifying fluid from it");raw.toggleMix();interval(raw);check.accept(l.getFluidState(rawPos.above()).isSource()&&l.getBlockState(rawPos.above()).is(Blocks.LAVA)&&raw.tank.isEmpty()&&raw.getItem(0).getCount()==3,"plain mode places foreign/native placeable fluid without consuming salts");
        l.setBlockAndUpdate(rawPos.above(),Blocks.AIR.defaultBlockState());raw.tank.fill(new FluidStack(Fluids.WATER,999),FluidAction.EXECUTE);interval(raw);check.accept(raw.tank.getFluidAmount()==999&&l.getBlockState(rawPos.above()).isAir(),"less than one bucket cannot place a partial source");
        var nether=l.getServer().getLevel(net.minecraft.world.level.Level.NETHER);var hot=create(nether,POS);hot.toggleMix();hot.tank.fill(new FluidStack(Fluids.WATER,1000),FluidAction.EXECUTE);nether.setBlockAndUpdate(POS.above(),Blocks.AIR.defaultBlockState());hot.serverTick();check.accept(nether.getBlockState(POS.above()).isAir()&&hot.tank.getFluidAmount()==1000,"original ultra-warm water placement rejection does not spend tank contents");
        var player=FakePlayerFactory.get(l,new GameProfile(UUID.fromString("01234567-1111-2222-3333-012345678906"),"SpaQA"));player.moveTo(Vec3.atCenterOf(rawPos));var menu=new ArcaneSpaMenu(1,player.getInventory(),raw,raw.data);boolean mode=raw.mixing();check.accept(menu.clickMenuButton(player,1)&&raw.mixing()!=mode&&!menu.clickMenuButton(player,99),"native menu button toggles mix mode and rejects unknown button IDs");player.moveTo(Vec3.atCenterOf(rawPos.east(20)));check.accept(!menu.clickMenuButton(player,1),"distant player cannot toggle a stale spa menu");player.moveTo(Vec3.atCenterOf(rawPos));raw.setItem(0,ItemStack.EMPTY);player.getInventory().setItem(9,new ItemStack(R4Content.BATH_SALTS.get(),2));check.accept(!menu.quickMoveStack(player,1).isEmpty()&&raw.getItem(0).getCount()==2,"shift-click moves bath salts into original dedicated slot");player.getInventory().setItem(9,new ItemStack(Items.COAL));check.accept(menu.quickMoveStack(player,1).isEmpty()&&player.getInventory().getItem(9).is(Items.COAL),"shift-click refuses non-salt inventory items");
        check.accept(menu.fluid().getFluid()==Fluids.WATER&&menu.fluid().getAmount()==999&&menu.mixing()==raw.mixing(),"menu synchronization conveys fluid registry identity, volume and mixing mode");
        var recipe=(thaumcraft.crafting.ArcaneRecipe)l.getRecipeManager().byKey(ResourceLocation.parse("thaumcraft:arcane_spa")).orElseThrow().value();var stacks=recipe.getIngredients().stream().map(g->g==Ingredient.EMPTY?ItemStack.EMPTY:g.getItems()[0].copy()).toList();var grid=CraftingInput.of(recipe.pattern().width(),recipe.pattern().height(),stacks);check.accept(recipe.matches(grid,l)&&recipe.assemble(grid,l.registryAccess()).is(R4Content.ARCANE_SPA.get().asItem())&&recipe.vis().values().stream().mapToInt(Integer::intValue).sum()==28,"source-derived Arcane Spa pattern produces registered device with original 28 vis");check.accept(thaumcraft.data.ThaumcraftData.get(l.getServer()).research().get("ARCANESPA").recipePages().contains("ArcaneSpa"),"original secondary spa research exposes native recipe page");
        if(spa.mixing())spa.toggleMix();spa.tank.setFluid(new FluidStack(thaumcraft.fluids.R4Fluids.PURE.get(),2345));spa.setItem(0,new ItemStack(R4Content.BATH_SALTS.get(),6));spa.sync();l.setBlockAndUpdate(POS.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());
    }
    static void reload(ServerLevel l,BiConsumer<Boolean,String> check){l.getChunkAt(POS);var spa=(ArcaneSpaBlockEntity)l.getBlockEntity(POS);check.accept(spa!=null&&!spa.mixing()&&spa.tank.getFluidAmount()==2345&&spa.tank.getFluid().is(thaumcraft.fluids.R4Fluids.PURE.get()),"spa mode, non-water fluid identity and exact amount survive real server restart");check.accept(spa.getItem(0).is(R4Content.BATH_SALTS.get())&&spa.getItem(0).getCount()==6,"bath salts inventory survives restart");spa.serverTick();check.accept(spa.tank.getFluidAmount()==2345,"saved redstone continues to inhibit placement after restart");var cap=l.getCapability(Capabilities.FluidHandler.BLOCK,POS,Direction.DOWN);check.accept(cap.drain(new FluidStack(thaumcraft.fluids.R4Fluids.PURE.get(),345),FluidAction.EXECUTE).getAmount()==345&&spa.tank.getFluidAmount()==2000,"restored tank supports native side drain capability");}
}
